<?php declare( strict_types=1 ); namespace Inc\Repositories\WPDBRepositories; use Inc\DTO\Exam\ExamPaymentLinkDTO; use Inc\Enums\Settings\TableName; class ExamPaymentLinkRepository { private \wpdb $wpdb; private string $table; public function __construct( ?\wpdb $wpdb = null ) { $this->wpdb = $wpdb ?? $GLOBALS['wpdb']; $this->table = TableName::ExamPaymentLinks->prefixed(); } public function insert( array $data ): int { $this->wpdb->insert( $this->table, $data ); return (int) $this->wpdb->insert_id; } public function find( int $id ): ?ExamPaymentLinkDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE id = %d", $this->table, $id ), ARRAY_A ); return $row ? ExamPaymentLinkDTO::fromArray( $row ) : null; } public function findByWcOrderItem( int $wcOrderItemId ): ?ExamPaymentLinkDTO { $row = $this->wpdb->get_row( $this->wpdb->prepare( "SELECT * FROM %i WHERE wc_order_item_id = %d", $this->table, $wcOrderItemId ), ARRAY_A ); return $row ? ExamPaymentLinkDTO::fromArray( $row ) : null; } public function findByApplication( int $applicationId ): array { $rows = $this->wpdb->get_results( $this->wpdb->prepare( "SELECT * FROM %i WHERE application_id = %d", $this->table, $applicationId ), ARRAY_A ); return array_map( [ ExamPaymentLinkDTO::class, 'fromArray' ], $rows ?: [] ); } public function update( int $id, array $data ): bool { return false !== $this->wpdb->update( $this->table, $data, [ 'id' => $id ] ); } }
